import React, { useEffect, useState } from "react";
import { socket } from "../api/socket";
import NamePrompt from "./NamePrompt";
import TimerBar from "./TimerBar";
import PollResults from "live_polling/frontend/src/components/PollResults.js";

export default function StudentView() {
  const [name, setName] = useState(null);
  const [poll, setPoll] = useState(null);
  const [selected, setSelected] = useState(null);
  const [hasSubmitted, setHasSubmitted] = useState(false);

  useEffect(() => {
    socket.on("poll:update", ({ poll }) => {
      setPoll(poll);
      setSelected(null);
      setHasSubmitted(false);
    });
    socket.on("poll:closed", () => {
      setHasSubmitted(true); // in case not submitted
    });
    return () => {
      socket.off("poll:update");
      socket.off("poll:closed");
    };
  }, []);

  const handleNameSet = n => {
    setName(n);
    socket.emit("student:register", { name: n });
  };

  const submitAnswer = () => {
    if (selected == null || !poll?.isActive) return;
    socket.emit("student:answer", { optionIndex: selected });
    setHasSubmitted(true);
  };

  if (!name) {
    return <NamePrompt onSetName={handleNameSet} />;
  }

  return (
    <div className="student-view">
      <p className="welcome">Hi, {name}</p>
      {!poll && <p>Waiting for the teacher to start a poll…</p>}

      {poll && (
        <div className="poll-card">
          <p className="poll-question">{poll.question}</p>

          {poll.isActive && (
            <>
              <TimerBar expiresAt={poll.expiresAt} />
              <ul className="poll-options">
                {poll.options.map((opt, idx) => (
                  <li key={idx}>
                    <label>
                      <input
                        type="radio"
                        name="answer"
                        disabled={hasSubmitted}
                        checked={selected === idx}
                        onChange={() => setSelected(idx)}
                      />
                      {opt}
                    </label>
                  </li>
                ))}
              </ul>
              <button
                disabled={hasSubmitted || selected == null}
                onClick={submitAnswer}
              >
                {hasSubmitted ? "Answer submitted" : "Submit"}
              </button>
            </>
          )}

          {(!poll.isActive || hasSubmitted) && (
            <div className="results-section">
              <h4>Live Results</h4>
              <PollResults poll={poll} />
            </div>
          )}
        </div>
      )}
    </div>
  );
}
